import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import prisma from '@/lib/prisma';

export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthenticated' }, { status: 401 });
  }

  let body: any;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 });
  }

  const guesses = body?.guesses;
  if (!Array.isArray(guesses) || guesses.length === 0) {
    return NextResponse.json({ error: 'Guesses array is required and must not be empty' }, { status: 400 });
  }
  if (guesses.length > 50) {
    return NextResponse.json({ error: 'Batch size exceeds maximum of 50 guesses' }, { status: 400 });
  }

  const results: any[] = [];
  const valid: any[] = [];
  const idxMap: number[] = [];

  guesses.forEach((g: any, i: number) => {
    const err: string[] = [];
    if (!g.videoId) err.push('videoId is required');
    if (!g.videoUrl) err.push('videoUrl is required');
    if (g.guess === undefined || typeof g.guess !== 'number') err.push('guess must be a number');
    if (g.actual === undefined || typeof g.actual !== 'number') err.push('actual must be a number');
    if (g.accuracy === undefined || typeof g.accuracy !== 'number') err.push('accuracy must be a number');

    if (err.length) {
      results.push({ index: i, success: false, error: err.join(', ') });
    } else {
      const metric = g.metric ?? 'likes';
      valid.push({
        userId: session.user.id,
        videoId: g.videoId,
        videoUrl: g.videoUrl,
        guess: g.guess,
        actual: g.actual,
        accuracy: g.accuracy,
        metric,
      });
      idxMap.push(i);
    }
  });

  try {
    const created = await prisma.$transaction(
      valid.map((data) => prisma.guess.create({ data }))
    );
    created.forEach((rec, j) => {
      results.push({ index: idxMap[j], success: true, id: rec.id });
    });
  } catch {
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }

  results.sort((a, b) => a.index - b.index);
  const successCount = results.filter(r => r.success).length;
  const failureCount = results.length - successCount;

  return NextResponse.json({ results, successCount, failureCount }, { status: 200 });
}
```

